	//       precompute beta * y[j]
	//       for each i (inner, contiguous dimension in A_T)
	//         x[i] += (beta*y[j]) * A_T[i,j]
	// - this keeps accesses to A_T and x mostly contiguous and reduces
	//   redundant multiplications by beta and y[j].
