	//
	// Simple vector addition. Traversal is 1D and fully contiguous.
	// ---------------------------------------------------------------------
	traverser(x, z).for_each([=](auto state) {
		x[state] = x[state] + z[state];
	});

	// ---------------------------------------------------------------------
	// 4) w[i] = w[i] + alpha * A[i][j] * x[j];
	//
	// We create a view of x indexed by 'j' so that x_j[j] == x[j].
	//
	// Optimization:
	// - still traverse A row‑by‑row (outer 'i', inner 'j');
	// - keep the accumulator for w[i] in a register:
	//     wi = w[i];
	//     wi += alpha * A[i][j] * x[j] for all j;
