		// state_i contains the current row index 'i'
		auto state_i = trav_i.state();

		// accumulate w[i] in a register
		num_t wi = w[state_i];

		trav_i.template for_each<'j'>([=, &wi](auto state) {
			// state has 'i' and 'j'; x_j only uses 'j', A uses both.
			wi += alpha * A[state] * x_j[state];
		});

		// write back once per row
		w[state_i] = wi;
	});

	#pragma endscop
}

