		auto A_full  = A  ^ cols_full_slice ^ j_block_proto;
		auto v1_full = v1 ^ cols_full_slice ^ j_block_proto;
		auto v2_full = v2 ^ cols_full_slice ^ j_block_proto;

		// Dimensions now: A_full has 'i' (rows), 'J' (block index), 'j' (in-block col)
		traverser(A_full, u1, v1_full, u2, v2_full)
			.template for_dims<'i'>([&](auto trav_i) {
				// trav_i: 'i' fixed, 'J' and 'j' remaining

				// Cache row-specific values of u1 and u2
				auto s_i = trav_i.state(); // contains index_in<'i'>
				num_t u1_i = u1[s_i];
				num_t u2_i = u2[s_i];

				// Iterate column blocks in this row
				trav_i.template for_dims<'J'>([&](auto trav_block) {
					// trav_block: 'i' and 'J' fixed, only 'j' remains

					trav_block.template for_each<'j'>([&](auto state) {
						// state has 'i', 'J', 'j' and can index all structures
						A_full[state] = A_full[state]
							+ u1_i * v1_full[state]
							+ u2_i * v2_full[state];
