		auto cols_tail_slice = noarr::slice<'j'>(full_cols, rem_cols);

		auto A_tail  = A  ^ cols_tail_slice;
		auto v1_tail = v1 ^ cols_tail_slice;
		auto v2_tail = v2 ^ cols_tail_slice;

		// Same computation as the original kernel, just restricted to the tail
		traverser(A_tail, u1, v1_tail, u2, v2_tail)
			.template for_dims<'i'>([&](auto trav_i) {
				auto s_i = trav_i.state();
