	// so floating-point results remain bitwise identical for each x[i].
	// ---------------------------------------------------------------------
	traverser(A).template for_dims<'i'>([&](auto trav_row) {
		// trav_row: one fixed row of A
		auto s_row = trav_row.state();
		std::size_t j = get_index<'i'>(s_row); // this 'i' acts as the 'j' in A[j][i]

		// y is indexed by 'j', so build a dedicated state for that index
