			auto s_x = noarr::idx<'i'>(i);

			x[s_x] += beta_yj * A[s];
		});
	});

	// ---------------------------------------------------------------------
	// 3) x[i] = x[i] + z[i];
	//
	// Straightforward element-wise vector addition.
	// ---------------------------------------------------------------------
	traverser(x, z).for_each([&](auto state) {
		x[state] = x[state] + z[state];
	});

	// ---------------------------------------------------------------------
	// 4) w[i] = w[i] + alpha * A[i][j] * x[j];
	//
	// Original version built a view of x indexed by 'j' (renaming) and then
	// traversed A row-major. We keep the good traversal order but:
	//  - avoid the extra renaming view;
	//  - accumulate w[i] in a register for each row and store once.
	//
	// This reduces the number of loads/stores to w and keeps A access
	// row-major (inner loop over 'j').
	// ---------------------------------------------------------------------
	traverser(A).template for_dims<'i'>([&](auto trav_row) {
		auto s_row = trav_row.state(); // fixed 'i'
		num_t wi = w[s_row];           // accumulate into a register

		trav_row.template for_each<'j'>([&](auto s) {
			std::size_t j = get_index<'j'>(s);
			auto s_x = noarr::idx<'i'>(j);

			wi += alpha * A[s] * x[s_x];
		});

		// write the final accumulated value once
		w[s_row] = wi;
	});

	#pragma endscop
}

